#!/usr/bin/env bash
#
# Builds distributable artifacts:
#   dist/chrome/                            unpacked extension (also used for Safari)
#   dist/members-portal-you-had-one-job.zip Chrome Web Store / manual install archive
#   dist/safari/                            Xcode project generated by Apple's converter
#
# Usage: bash scripts/build.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DIST="$ROOT/dist"
SRC="$ROOT/src"

rm -rf "$DIST/chrome" "$DIST/safari" "$DIST"/*.zip
mkdir -p "$DIST/chrome"
cp -R "$SRC/." "$DIST/chrome/"
(cd "$DIST/chrome" && zip -qr "$DIST/members-portal-you-had-one-job.zip" .)
echo "Chrome build:  $DIST/chrome"
echo "Chrome zip:    $DIST/members-portal-you-had-one-job.zip"

if xcrun --find safari-web-extension-converter >/dev/null 2>&1; then
  echo "Generating Safari project…"
  xcrun safari-web-extension-converter "$DIST/chrome" \
    --project-location "$DIST/safari" \
    --app-name "Members portal, you had one job" \
    --bundle-identifier "ai.motionlab.members-portal-you-had-one-job" \
    --copy-resources \
    --no-open \
    --no-prompt \
    --force
  echo "Safari project: $DIST/safari"
else
  echo "Safari converter not found (install Xcode to build the Safari app)."
fi
